typedef struct BlockEntry
{
    const char *name;
    const char *id;
    LIBMATTI_MC_Block *block;
} BlockEntry;

static BlockEntry entries[1142];
static int initialized = 0;

// Java: the createBlockStateDefinition(...) add() list of the block class
static LIBMATTI_MC_Property **state_properties(const char *const *names, int count)
{
    // unused generic indirection - the states are built per block below
    (void) names;
    (void) count;
    return NULL;
}

static void init_entry(int index, const char *name, const char *id,
                         LIBMATTI_MC_BlockBehaviour_Properties *properties,
                         LIBMATTI_MC_Property *const *stateProps, int statePropCount)
{
    entries[index].name = name;
    entries[index].id = id;
    // Java: the state definition builder + the block constructor owner rewiring
    LIBMATTI_MC_StateDefinition_Builder *builder = LIBMATTI_MC_StateDefinition_Builder_New(NULL);
    for (int i = 0; i < statePropCount; i++)
        LIBMATTI_MC_StateDefinition_Builder_Add(builder, stateProps[i]);
    LIBMATTI_MC_StateDefinition *definition = LIBMATTI_MC_StateDefinition_Builder_Create(builder);
    LIBMATTI_MC_Block *block = LIBMATTI_MC_Block_NewWithPropertiesAndStateDefinition(properties, definition);
    entries[index].block = block;
}

