// Java: the static initialisation of Blocks
void LIBMATTI_MC_VanillaBlocks_Initialize(void)
{
    initialize();
}

// Java: private static Block register(String key, ...) - Registry.register through the
// BuiltInRegistries.BLOCK (ResourceKey.create(Registries.BLOCK, id)); the setId path of
// the properties runs here like in Java
void LIBMATTI_MC_VanillaBlocks_RegisterAll(void)
{
    initialize();
    LIBMATTI_MC_MappedRegistry *registry = LIBMATTI_MC_BuiltInRegistries_BLOCK();
    for (int i = 0; i < LIBMATTI_MC_VanillaBlocks_COUNT; i++)
    {
        LIBMATTI_MC_Identifier *identifier =
            LIBMATTI_MC_Identifier_FromNamespaceAndPath("minecraft", entries[i].id);
        LIBMATTI_MC_ResourceKey *key = LIBMATTI_MC_ResourceKey_Create(
            LIBMATTI_MC_Registries_BLOCK(), identifier);
        LIBMATTI_MC_BlockBehaviour_Properties_SetId(LIBMATTI_MC_Block_GetProperties(entries[i].block), key);
        entries[i].block->key = key;
        LIBMATTI_MC_Registry_RegisterWithIdentifier(registry, identifier, entries[i].block);
        LIBMATTI_MC_Identifier_Free(identifier);
    }
}

LIBMATTI_MC_Block **LIBMATTI_MC_VanillaBlocks_All(void)
{
    initialize();
    static LIBMATTI_MC_Block **blocks = NULL;
    if (blocks == NULL)
    {
        blocks = malloc(sizeof(LIBMATTI_MC_Block *) * LIBMATTI_MC_VanillaBlocks_COUNT);
        for (int i = 0; i < LIBMATTI_MC_VanillaBlocks_COUNT; i++)
            blocks[i] = entries[i].block;
    }
    return blocks;
}

LIBMATTI_MC_Block *LIBMATTI_MC_VanillaBlocks_GetByName(const char *name)
{
    initialize();
    for (int i = 0; i < LIBMATTI_MC_VanillaBlocks_COUNT; i++)
        if (strcmp(entries[i].name, name) == 0)
            return entries[i].block;
    return NULL;
}

const char *LIBMATTI_MC_VanillaBlocks_IdOf(LIBMATTI_MC_Block *block)
{
    initialize();
    for (int i = 0; i < LIBMATTI_MC_VanillaBlocks_COUNT; i++)
        if (entries[i].block == block)
            return entries[i].id;
    return NULL;
}

LIBMATTI_MC_Block *LIBMATTI_MC_VanillaBlocks_AIR(void)
{
    initialize();
    return entries[AIR].block;
}
